import json
from pathlib import Path
P=Path(__file__).parent;PID='icml2024-layerwise';SID='src-icml2024-layerwise-formal'
issues=[]
def issue(id,title,etitle,kind,pages,original,desc,edesc,evidence,eevidence,impact,eimpact):
 issues.append(dict(id=id,paper_id=PID,title=title,kind=kind,source_refs=[dict(source_id=SID,pdf_pages=pages)],original_expression=original,description_md=desc,evidence_md=evidence,impact_md=impact,user_confirmation='not_individually_confirmed',fix_authorization='proof_only_granted',proposition_modification_authorized=False,status='agent_checked',translations={'en':dict(title=etitle,description_md=edesc,evidence_md=eevidence,impact_md=eimpact)}))
issue('layer-issue-binomial-15','Eq.(15) 缺失二项式系数','Missing binomial multiplicities in Eq.(15)','proof_error',[15],r'\sum_{m=0}^{|T|-|L|}(-1)^m=0','作者按阶数汇总子集时漏掉组合数量。','The author groups subsets by size without their multiplicities.',r'$|T|-|L|=2$ 时原和为 $1-1+1=1$，并非 $0$；正确和为 $1-2+1=0$。',r'For $|T|-|L|=2$, the printed sum is $1-1+1=1$, rather than $0$; the correct sum is $1-2+1=0$.','同一重构命题用完整二项式消去补正，原错式保留。','The same reconstruction claim is repaired by full binomial cancellation; the erroneous source expression is retained.')
issue('layer-issue-or-calculation-16','Eq.(16) OR 分组的零因子不成立','Invalid zero-factor grouping in Eq.(16)','proof_error',[15],r'\sum_{S_1\subseteq N\setminus T\setminus L}(\cdots)=0','原分组的符号缺少固定 L 与 T 交集的指数；零因子仍须按两个剩余块完整核对。','The grouping omits the fixed-L intersection exponent; zero factors must still be checked using both remaining blocks.',r'取 $N=\{1,2\},T=\{1\},L=\{1\}$，原式 $S_1=\varnothing,\{2\}$ 的符号与原 $|S|-|L|$ 相反。其分组总和虽可由剩余块消去，但这不使逐项错符号相等。',r'For $N=\{1,2\},T=\{1\},L=\{1\}$, the printed signs for $S_1=\varnothing,\{2\}$ are opposite to the original exponent $|S|-|L|$. The grouped sum can still cancel using its remaining blocks, which does not make the printed termwise signs equal.','用全 OR 和减去不激活 OR 和完整补证，不改变定理。','Subtracting the inactive OR sum from the full OR sum repairs the proof without changing the theorem.')
issue('layer-issue-conditional-scope','固定与条件 OR 游戏不可混换','Fixed and conditional OR games differ','scope_mismatch',[4,15],r'I_{or}(S\mid x_T)\ne I_{or}(S\mid x)\ \text{in general}','AND 在 S⊆T 时可限制相等；OR 补集变换在再次掩码后通常改变。','AND restriction agrees for S contained in T; the OR complementary transform generally changes under repeated masking.',r'$N=\{1,2\}$，$o(U)=\mathbf1_{\{1,2\}\subseteq U}$，$T=\{1\}$：固定 $O(\{1\})=1$，限制游戏 $o_T\equiv0$ 的 $O_T(\{1\})=0$。',r'For $N=\{1,2\}$, $o(U)=\mathbf1_{\{1,2\}\subseteq U}$, and $T=\{1\}$, fixed $O(\{1\})=1$, while $o_T\equiv0$ yields $O_T(\{1\})=0$.','两种重构均证明；限制分解与独立重新学习的分解须分别实例化。','Both reconstruction forms are proved. A restricted split and an independently relearned split must be instantiated separately.')
issue('layer-issue-empty-or','Eq.(2) 字面空集值与定理特设值不同','Eq.(2) has a different literal empty value','undefined_original_scope',[4],r'-\sum_{T\subseteq\varnothing}(-1)^{0-|T|}o(N\setminus T)=-o(N)','Definition 3.2 对所有 S 的公式在空集不等于随后特设基线。','The all-S formula in Definition 3.2 differs at the empty set from the later special baseline.',r'$o(\varnothing)=0,o(N)=1$ 给原公式空值 $-1$，而定理空值 $0$。',r'$o(\varnothing)=0,o(N)=1$ gives literal empty value $-1$, while the theorem specifies $0$.','非空负变换与原定理空集约定分开保存。','The nonempty negative transform and the theorem’s empty convention are retained separately.')
issue('layer-issue-baseline-19','Eq.(19) 重复加入输出基线','Duplicated output baseline in Eq.(19)','proof_error',[16],r'g(T)=b+\sum_{S\subseteq T}A_T(S)+\sum_{S\cap T\ne\varnothing}O_T(S)','AND 求和已经含空集基线，原式又加了一次。','The AND sum already contains the empty baseline, which is added again.',r'$g\equiv1,a\equiv1,o\equiv0$ 满足原空分量条件，原右端为 $1+1=2\ne1$。',r'$g\equiv1,a\equiv1,o\equiv0$ satisfies the stated empty-component conditions, but the printed right side is $1+1=2\ne1$.','保留显式 b 时删去 AND 求和中的空项；这修复中间式，不解决显著近似的外引缺口。','Exclude the empty AND term when keeping explicit b. This repairs the intermediate equality without resolving the external sparse-approximation gap.')
issue('layer-issue-sparse-transfer','Lemma 3.4 与 OR 稀疏外引条件未验证','Unverified external conditions for Lemma 3.4 and OR sparsity','external_scope_issue',[3,4,13,16],r'O(S)=-I_h(S)\not\Rightarrow\#\{S:O(S)\ne0\}\ll2^n','补集代数等式不能自动保证学习分量满足所引稀疏定理条件。','The complementary algebraic identity does not establish that learned components satisfy the cited sparsity theorem’s conditions.','原文缺少对 AND 分量、OR 分量补集游戏的条件检验，也没有给“小”和近似误差的定量定义。','The source does not check the assumptions for the AND component and complemented OR component, or quantify smallness and approximation error.','完整原文仍保留，项目给出尾和条件界并将原断言范围标为未完成，未偷添条件。','The full source remains available. A separate tail-bound result is supplied, while the original assertion’s scope remains unresolved without inserted assumptions.')
issue('layer-issue-coordinate-13','Eq.(12) 不是所需反向掩码','Eq.(12) is not the required reversed mask','false_under_displayed_definitions',[13],r"v(x_{N\setminus T})=v(x'_T)",'原两坐标定义实际互补，Eq.(13) 的第二等号错误。','The two printed coordinate definitions are complementary, making the second equality in Eq.(13) false.',r'$N=T=\{1\},x_1=1,r_1=0,v(z)=z_1$ 给 $0\ne1$。',r'$N=T=\{1\},x_1=1,r_1=0,v(z)=z_1$ gives $0\ne1$.','原坐标错式独立登记；游戏层面的补集负变换证明有效，不把新定义换进原式。','The coordinate error is recorded separately. The complementary-game negative transform remains valid; a new coordinate definition is not substituted into the source.')
issue('layer-issue-strength-8','Eq.(8) 在原显著支持下第一等式失败','The first Eq.(8) identity fails with the stated salient supports','false_original_statement',[5,6,7],r'\operatorname{all}_{l,1}=\operatorname{overlap}_{l,1}+\operatorname{forget}_{l,1}','重叠项只在共同显著支持求和，忘记项却从每个本层显著系数减去实际共享值。','Overlap uses only the common salient support, while forget subtracts the actual shared coefficient at every current-layer salient coalition.',r'归一化纯 AND 系数本层 $(1/2,1/2)$、末层 $(1/101,100/101)$；原阈值给支持 $\{\{1\},\{2\}\}$ 与 $\{\{2\}\}$。$\operatorname{all}_{l,1}=1$，$\operatorname{overlap}_{l,1}+\operatorname{forget}_{l,1}=1/2+99/202=100/101$。两分解 L1=1 全局最优。',r'Normalized pure AND coefficients are $(1/2,1/2)$ and $(1/101,100/101)$. The stated thresholds give supports $\{\{1\},\{2\}\}$ and $\{\{2\}\}$. Then $\operatorname{all}_{l,1}=1$, while $\operatorname{overlap}_{l,1}+\operatorname{forget}_{l,1}=1/2+99/202=100/101$. Both splits are globally L1-optimal at value 1.','第一子句有完整反例；本例第二子句成立。不能用正确标量引理冒充原总式证明。','The first clause has a full counterexample; the second holds in this witness. The valid scalar lemma does not prove the printed aggregate identity.')
issue('layer-issue-zero-metrics','比值、平均与归一化的零边界未规定','Unspecified zero boundaries of ratios, averages, and normalization','undefined_original_scope',[5,7,8,21],r'0/0','空并集、零总强度、零方差、空显著集合或零归一化因子会产生未定义实数表达。','An empty union, zero total strength, zero variance, empty salient family, or zero normalization factor can make the real expression undefined.','原文未分别给这些情况的赋值规则；残差严格界在 κ=0 时也无可行解。','The source supplies no separate values for these cases; its strict residual bound is also infeasible when κ=0.','只在原表达有定义时解释数值，不新增隐含零值约定。','Interpret the metrics where their original expressions are defined, without adding a hidden zero convention.')
(P/'issues.json').write_text(json.dumps({'paper_id':PID,'issues':issues},ensure_ascii=False,indent=2)+'\n')
symbols=[]
def sym(id,tex,name,en,definition,desc,edesc,pages,original=None,empty='不省略空集作用域；使用相关条目的显式约定。',eempty='The empty-set scope follows the explicit convention of the relevant entry.'):
 symbols.append(dict(id=id,canonical_tex=tex,name_zh=name,definition_tex=definition,description_md=desc,type_or_domain='Finite sets, real values, or explicitly specified vectors/probabilities',scope='icml2024-layerwise; fixed input/baseline/layer/decomposition where applicable',assumptions=[],empty_set_convention=empty,baseline_convention='原始输出基线不默认零；输入基线向量与分类器截距单独标识。',aliases=[original or tex],paper_mappings=[dict(paper_id=PID,version_id='ver-icml2024-layerwise-formal',source_id=SID,original_tex=original or tex,original_definition=definition,pdf_pages=pages,canonical_concept=id,relationship='renaming')],lean_names=[],version='1.0',translations={'en':dict(name_zh=en,description_md=edesc,empty_set_convention=eempty,baseline_convention='The raw output baseline is not assumed zero; input baseline vectors and probe intercepts are distinguished.')}))
sym('model-output',r'v:X\to\mathbb R','实值模型输出','Real-valued model output',r'g(S)=v(x_S)','给定分类分数或某层探针的实值输出。','A specified classification score or real-valued layer-probe output.',[3,5])
sym('masked-input',r'x_S','保留集掩码输入','Retained-set masked input',r'(x_S)_i=\begin{cases}x_i&i\in S,\\r_i&i\notin S\end{cases}','保留 S 内坐标，其余取同一输入基线。','Retain coordinates in S and use the same input baseline elsewhere.',[3,13],r'x_T')
sym('set-game',r'g(S)','掩码集合函数','Masked set game',r'g(S)=v(x_S)','固定模型、输入、输入基线后得到的有限集合函数。','The finite set function determined by a fixed model, input, and input baseline.',[3,4],r'v(x_T)')
sym('output-baseline',r'b','输出基线标量','Scalar output baseline',r'b=g(\varnothing)=v(x_\varnothing)','空掩码输出，不是输入基线向量。','The empty-mask output, distinct from an input baseline vector.',[4,15,16],r'v(x_\varnothing)')
sym('input-baseline',r'r','输入基线向量','Input baseline vector',r'r=(r_i)_{i\in N}','原 b_i 是输入坐标的遮罩值。','The source b_i is the masked value of input coordinate i.',[3,13],r'b_i')
sym('layer-and-component',r'a_l(S)','AND 输出分量','AND output component',r'a_l(S)=g_l(S)/2+\gamma_{l,S}','固定分解的 AND 游戏，区别于总游戏。','The AND game of a fixed split, distinct from the total game.',[3,4],r'v_{and}(x_S)')
sym('layer-or-component',r'o_l(S)','OR 输出分量','OR output component',r'o_l(S)=g_l(S)/2-\gamma_{l,S}','固定分解的 OR 游戏。','The OR game of a fixed split.',[3,4],r'v_{or}(x_S)')
sym('layer-gamma',r'\gamma_{l,S}','分解学习参数','Learned split parameter',r'a_l+o_l=g_l','随层和掩码定义的确定性参数。','A deterministic parameter indexed by layer and mask.',[3,4,5],r'\gamma_T')
sym('layer-and-interaction',r'A_l(S)','AND 分量交互','AND component dividend',r'A_l(S)=\sum_{T\subseteq S}(-1)^{|S|-|T|}a_l(T)','总输出的 Eq.(1) 与分量 AND 需按作用域区分。','Distinguish Eq.(1) for the total output from AND dividends of a component.',[3,4],r'I_{and}(S\mid x,v^{(l)})',empty='A_l(空集)=a_l(空集)，定理条件下等于输出基线。',eempty='A_l(empty)=a_l(empty), equal to the output baseline under the theorem’s stated condition.')
sym('layer-or-interaction',r'O_l(S)','非空 OR 分量交互','Nonempty OR component dividend',r'O_l(S)=-\sum_{T\subseteq S}(-1)^{|S|-|T|}o_l(N\setminus T)\ (S\ne\varnothing)','非空负补集变换与空集特设约定分开。','The nonempty negative complementary transform is separate from the special empty convention.',[4],r'I_{or}(S\mid x,v^{(l)})',empty='原定理空集取 o_l(空集)=0；Eq.(2) 字面空集值 −o_l(N) 是独立来源问题。',eempty='The theorem uses empty value o_l(empty)=0; the literal Eq.(2) value −o_l(N) is a separate source issue.')
sym('layer-conditional-game',r'g_{l,T}(U)','再次掩码条件游戏','Repeated-mask conditional game',r'g_{l,T}(U)=g_l(T\cap U)','固定分解可限制，独立再学习的分解另实例化。','A fixed split may be restricted; an independently relearned split is a separate instance.',[4,15],r'I(S\mid x_T)')
sym('layer-probe',r'p^{(l)}(y\mid x)','线性探针预测概率','Linear-probe probability',r'p^{(l)}=\operatorname{softmax/sigmoid}((w^{(l)})^{\mathsf T}f^{(l)}+b^{(l)})','原 DNN 固定，探针另训练。','The DNN is fixed while the probe is trained separately.',[5,22])
sym('layer-feature',r'f^{(l)}(x)','中间层特征','Intermediate-layer feature',r'f^{(l)}:X\to\mathbb R^{d_l}','向量特征不是直接参与 Möbius 变换的实值游戏。','A vector feature is distinct from the real-valued game transformed by Möbius inversion.',[5])
sym('layer-probe-intercept',r'b^{(l)}','探针截距','Probe intercept',r'(w^{(l)})^{\mathsf T}f^{(l)}(x)+b^{(l)}','不等于输入基线或输出基线。','Distinct from the input or output baseline.',[5])
sym('layer-residual',r'\delta_T','可学习残差','Learned residual',r'|\delta_T|<\kappa','确定性优化参数，不是高斯噪声。','A deterministic optimization parameter, distinct from Gaussian noise.',[5,20])
sym('layer-residual-bound',r'\kappa','残差上限','Residual bound',r'\kappa=.04|g_l(N)-g_l(\varnothing)|','零差值时原严格约束没有可行解。','The strict source constraint is infeasible at a zero output difference.',[5,20])
sym('layer-order',r'm=|S|','交互阶数','Interaction order',r'm=|S|','交互中的变量数，不是样本数。','The number of variables in a coalition, distinct from sample count.',[5,8])
sym('layer-threshold',r'\tau_l','显著性交互阈值','Saliency threshold',r'\tau_l=.05\max_S\max\{|A_l(S)|,|O_l(S)|\}','脚注 7 与附录 M.4 的跨样本阈值分开标识。','The footnote 7 threshold is distinct from Appendix M.4’s cross-sample maximum.',[5,22],r'\tau')
sym('layer-salient-family',r'\Omega_{and}^{l,m}','显著交互集合族','Salient coalition family',r'\Omega_{and}^{l,m}=\{S\subseteq N:|S|=m,|A_l(S)|>\tau_l\}','元素是变量集合 S；OR 类似。','Its elements are coalitions S; the OR family is analogous.',[5,6],r'\Omega_{and}^{(l),m}')
sym('layer-shared',r's_S','有符号共享交互','Signed shared interaction',r's_S=s(A_l(S),A_L(S))','同号取最小幅度，异号取零。','Use the smaller magnitude for matching signs and zero for opposite signs.',[6])
sym('layer-all-strength',r'\operatorname{all}_{l,m}','显著交互总强度','Total salient strength',r'\operatorname{all}_{l,m}=\sum_{S\in\Omega_l}|A_l(S)|','仅对指定阶显著支持求和。','Sum over the salient support of the specified order.',[6])
sym('layer-overlap',r'\operatorname{overlap}_{l,m}','共同显著共享强度','Shared strength on common salient support',r'\operatorname{overlap}_{l,m}=\sum_{S\in\Omega_l\cap\Omega_L}|s_S|','注意与 forget/new 的求和支持不同。','Its support differs from those of forget and new.',[6])
sym('layer-forget-new',r'\operatorname{forget}_{l,m},\operatorname{new}_{l,m}','忘记与新增强度','Forgotten and new strength',r'\operatorname{forget}_{l,m}=\sum_{S\in\Omega_l}|A_l(S)-s_S|,\quad\operatorname{new}_{l,m}=\sum_{S\in\Omega_L}|A_L(S)-s_S|','各自遍历本层/末层显著支持，subtract 实际共享系数。','Range over current/final salient supports respectively, subtracting the actual shared coefficient.',[6])
sym('layer-normalization',r'c_l','层间归一化因子','Layer normalization factor',r'c_l=\mathbb E_x|g_l(N)-g_l(\varnothing)|','脚注 8 的正缩放，不改变该层相对阈值；为零时未定义。','Footnote 8’s positive scaling preserves that layer’s relative threshold; zero is undefined.',[7])
sym('layer-ratios',r'\operatorname{completeness},\operatorname{redundancy}','完备度与冗余度指标','Completeness and redundancy metrics',r'\operatorname{completeness}=\operatorname{overlap}/\operatorname{all}_L,\quad\operatorname{redundancy}=\operatorname{forget}/\operatorname{all}_l','名称不是额外语义保证。','The names are not additional semantic guarantees.',[7])
sym('layer-iou',r'\operatorname{IoU}(\mathcal A,\mathcal B)','集合交并比','Intersection over union',r'\operatorname{IoU}=|\mathcal A\cap\mathcal B|/|\mathcal A\cup\mathcal B|','同阶显著集合族的交并比；空并集原式未定义。','The IoU of same-order salient families; an empty union is undefined in the source.',[8])
sym('layer-noise',r'\epsilon','随机输入扰动','Random input perturbation',r'\epsilon\sim\mathcal N(0,\sigma^2I)','随机变量区别于可学习残差。','A random variable distinct from the learned residual.',[8,21])
sym('layer-moments',r'\mu_l(S,x),\nu_l(S,x)','噪声交互均值与方差','Mean and variance of noisy dividends',r'\mu_l=\mathbb E_\epsilon A_l(S\mid x+\epsilon),\quad\nu_l=\operatorname{Var}_\epsilon A_l(S\mid x+\epsilon)','定义对应真实噪声，不是对样本/层的混合平均。','Moments over actual perturbations, distinct from averages over samples or layers.',[8,21])
sym('layer-stability',r'\operatorname{stability}_{and}^{l,m}','相对稳定性指标','Relative stability metric',r'\mathbb E_x\mathbb E_{S\in\Omega_l}|\mu_l(S,x)|/\sqrt{\nu_l(S,x)}','零方差和空显著集合未给约定。','Zero variance and empty salient families have no specified convention.',[8,21])
sym('layer-noise-ratio',r'\operatorname{Ratio}^{\epsilon}_S','输入模式噪声比例','Input-pattern noise ratio',r'\|x_S-x_S^\epsilon\|_2/\|x_S\|_2','Figure 12 的输入范数比，不是稳定性的交互方差。','The input-norm ratio in Figure 12, distinct from interaction variance in stability.',[21],r'\operatorname{Radio}^{\epsilon}_S')
sym('layer-shapley',r'\varphi_g(i)','经典 Shapley 归因','Classical Shapley attribution',r'\varphi_g(i)=\sum_{U\subseteq N\setminus\{i\}}\frac{|U|!(n-|U|-1)!}{n!}[g(U\cup\{i\})-g(U)]','从边际定义推出 AND/OR 均分，不以均分作为定义。','Derive AND/OR sharing from the marginal definition, rather than defining it as sharing.',[13],r'\phi(i)')
(P/'symbols.json').write_text(json.dumps({'paper_id':PID,'symbols':symbols},ensure_ascii=False,indent=2)+'\n')
